#Requires -Version 5.1
<#
.SYNOPSIS
  Добавляет русскую локализацию в десктопный клиент Kimi Code (Windows).

.DESCRIPTION
  Патчит JS-бандлы приложения: добавляет словарь ru, разрешает локаль "ru"
  и добавляет пункт «Русский» в переключатель языка в настройках.
  Оригинальные файлы сохраняются рядом с расширением .orig.

.PARAMETER InstallDir
  Папка установки Kimi Code (по умолчанию ищется автоматически).

.PARAMETER Restore
  Откат: восстанавливает оригинальные файлы из .orig.

.EXAMPLE
  powershell -ExecutionPolicy Bypass -File install.ps1

.EXAMPLE
  powershell -ExecutionPolicy Bypass -File install.ps1 -Restore
#>
param(
    [string]$InstallDir,
    [switch]$Restore
)

$ErrorActionPreference = 'Stop'

function Test-IsAdmin {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $p  = New-Object Security.Principal.WindowsPrincipal($id)
    return $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Test-DirWritable([string]$Path) {
    $probe = Join-Path $Path ('.write-test-' + [guid]::NewGuid().ToString('N'))
    try {
        [IO.File]::WriteAllText($probe, 'x')
        Remove-Item -LiteralPath $probe -Force
        return $true
    } catch {
        return $false
    }
}

function Resolve-InstallDir([string]$Explicit) {
    $candidates = @()
    if ($Explicit) { $candidates += $Explicit }
    $candidates += @(
        (Join-Path $env:ProgramFiles 'Kimi Code'),
        (Join-Path ${env:ProgramFiles(x86)} 'Kimi Code'),
        (Join-Path $env:LOCALAPPDATA 'Programs\Kimi Code')
    ) | Where-Object { $_ }
    foreach ($d in $candidates) {
        if (Test-Path (Join-Path $d 'resources\desktop-dist\assets')) { return $d }
    }
    throw 'Kimi Code не найден. Укажите папку вручную: -InstallDir "C:\Program Files\Kimi Code"'
}

function Get-AssetFile([string]$Assets, [string]$Pattern) {
    $f = Get-ChildItem -LiteralPath $Assets -Filter $Pattern |
         Where-Object { $_.Name -notlike '*.orig' } |
         Select-Object -First 1
    if (-not $f) { throw "Файл $Pattern не найден в $Assets. Возможно, структура приложения изменилась." }
    return $f
}

function Backup-Once([string]$Path) {
    $bak = "$Path.orig"
    if (-not (Test-Path $bak)) {
        Copy-Item -LiteralPath $Path -Destination $bak
        Write-Host "Бэкап: $bak"
    }
}

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    [IO.File]::WriteAllText($Path, $Text, (New-Object System.Text.UTF8Encoding($false)))
}

function Get-RuJson {
    $b64 = @'

'@
    $bytes = [Convert]::FromBase64String($b64)
    $ms = New-Object IO.MemoryStream(, $bytes)
    $gz = New-Object IO.Compression.GzipStream($ms, [IO.Compression.CompressionMode]::Decompress)
    $sr = New-Object IO.StreamReader($gz, [Text.Encoding]::UTF8)
    try { return $sr.ReadToEnd() } finally { $sr.Close(); $gz.Close(); $ms.Close() }
}

$root   = Resolve-InstallDir $InstallDir
$assets = Join-Path $root 'resources\desktop-dist\assets'
Write-Host "Kimi Code: $root"

$segFile  = Get-AssetFile $assets 'SegmentedControl-*.js'
$mainFile = Get-AssetFile $assets 'main-*.js'

# --- Откат ---
if ($Restore) {
    if (-not (Test-DirWritable $assets) -and -not (Test-IsAdmin)) {
        Write-Host 'Требуются права администратора — подтвердите запрос UAC...'
        $cmd = "& `"$PSCommandPath`" -Restore"
        if ($InstallDir) { $cmd += " -InstallDir `"$InstallDir`"" }
        $enc = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($cmd))
        $p = Start-Process powershell -Verb RunAs -ArgumentList '-NoProfile','-EncodedCommand',$enc -Wait -PassThru
        exit $p.ExitCode
    }
    foreach ($f in @($segFile, $mainFile)) {
        $bak = "$($f.FullName).orig"
        if (Test-Path $bak) {
            Copy-Item -LiteralPath $bak -Destination $f.FullName -Force
            Write-Host "Восстановлено: $($f.Name)"
        } else {
            Write-Host "Бэкап не найден, пропущено: $($f.Name)"
        }
    }
    Write-Host "`nОткат завершён. Перезапустите Kimi Code."
    exit 0
}

# --- Установка ---
$segText  = [IO.File]::ReadAllText($segFile.FullName)
$mainText = [IO.File]::ReadAllText($mainFile.FullName)

if ($segText.Contains('Ye={en:ae,zh:Ge,ru}') -and $mainText.Contains('code:"ru",label:"Русский"')) {
    Write-Host 'Русская локализация уже установлена. Ничего не делаю.'
    exit 0
}

$oldLocaleSwitch = 'Ye={en:ae,zh:Ge}'
$oldDetect = 'return e==="en"||e==="zh"?e:globalThis.navigator?.language?.toLowerCase().startsWith("zh")?"zh":"en"'
$newDetect = 'return e==="en"||e==="zh"||e==="ru"?e:globalThis.navigator?.language?.toLowerCase().startsWith("zh")?"zh":globalThis.navigator?.language?.toLowerCase().startsWith("ru")?"ru":"en"'
$oldLangList = 'Nk=[{code:"en",label:"English"},{code:"zh",label:"简体中文"}]'
$newLangList = 'Nk=[{code:"en",label:"English"},{code:"zh",label:"简体中文"},{code:"ru",label:"Русский"}]'

if (-not $segText.Contains($oldLocaleSwitch) -or -not $segText.Contains($oldDetect) -or -not $mainText.Contains($oldLangList)) {
    throw @'
Эта версия Kimi Code не поддерживается: не найдены ожидаемые участки кода.
Файлы НЕ изменены. Если приложение обновилось — дождитесь новой версии скрипта
или откройте issue: https://github.com/fedorka812/kimi-code-ru/issues
'@
}

if (-not (Test-DirWritable $assets) -and -not (Test-IsAdmin)) {
    Write-Host 'Требуются права администратора — подтвердите запрос UAC...'
    $cmd = "& `"$PSCommandPath`""
    if ($InstallDir) { $cmd += " -InstallDir `"$InstallDir`"" }
    $enc = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($cmd))
    $p = Start-Process powershell -Verb RunAs -ArgumentList '-NoProfile','-EncodedCommand',$enc -Wait -PassThru
    exit $p.ExitCode
}

$ruJson = Get-RuJson
$ruDecl = 'const ru=' + $ruJson + ";`n"

Backup-Once $segFile.FullName
Backup-Once $mainFile.FullName

$segText = $ruDecl + $segText
$segText = $segText.Replace($oldLocaleSwitch, 'Ye={en:ae,zh:Ge,ru}')
$segText = $segText.Replace($oldDetect, $newDetect)
$mainText = $mainText.Replace($oldLangList, $newLangList)

Write-Utf8NoBom $segFile.FullName $segText
Write-Utf8NoBom $mainFile.FullName $mainText

Write-Host @'

Готово! Русская локализация установлена.

Полностью закройте Kimi Code и запустите снова.
Язык определится автоматически (русская Windows) либо выберите
«Русский» в настройках → Language.

Откат:  powershell -ExecutionPolicy Bypass -File install.ps1 -Restore
После обновления Kimi Code запустите этот скрипт ещё раз.
'@
